  notes jsonb := '{"0026041": "19-in Black Alloy Wheels $2176 + TPMS Sensors $108.2", "0026076": "20-in Black Alloy Wheels with Tires $2612 + TPMS Sensors $108.2 + 20-in Wheel, Tire $855.04", "0026036": "Hands-Free Access Power Tailgate $326 + HFA-Sensor Attachment $116", "0026079": "Trailer Hitch $464 + Trailer Hitch Trim Cover $121 + Trailer Hitch Harness $230", "0026042": "20-in Black Alloy Wheels $2612 + TPMS Sensors $108.2", "0026074": "Hands-Free Access Power Tailgate $320 + HFA-Sensor Attachment $116", "0026083": "Trailer Hitch $464 + Trailer Hitch Trim Cover $121 + Trailer Hitch Harness $230 + HFA Sensor - Short $230"}'::jsonb;
